args.content:
SELECT ?item ?itemLabel ?coords
WHERE {
  ?item wdt:P31/wdt:P279* wd:Q8813 ;
        wdt:P625 ?coords .
  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "en" .
  }
  BIND(?item AS ?item)
  BIND(STR(?item) AS ?itemLabel)
}
LIMIT 100

